"""Hand-computed expected answers.

Every number here is derived on paper from the fixture definitions in
``app/reproducibility/fixtures.py``; nothing here imports the estimation core.
These constants are the ground truth the tests assert against. They are the
"reference answers [that] are not generated by the implementation under test".
"""
from __future__ import annotations

# --- hand_2x2 ------------------------------------------------------------- #
# t1: 2 -> 5 (change 3), t2: 4 -> 9 (change 5)
# c1: 1 -> 1 (change 0), c2: 3 -> 5 (change 2)
HAND_2X2 = {
    "treat_pre": 3.0,        # (2 + 4) / 2
    "treat_post": 7.0,       # (5 + 9) / 2
    "control_pre": 2.0,      # (1 + 3) / 2
    "control_post": 3.0,     # (1 + 5) / 2
    "treat_change": 4.0,
    "control_change": 1.0,
    "did": 3.0,
    "n_treat": 2,
    "n_control": 2,
    # Clustered CRV1 standard error of b, derived analytically in the docs:
    # X'X^-1 = [[.5,-.5],[-.5,1]], meat=[[4,2],[2,2]], factor = 4/3*3/2 = 2,
    # vcov_b = 2 -> se = sqrt(2).
    "se": 2.0 ** 0.5,
    "ci_low": 3.0 - 3.182446305 * (2.0 ** 0.5),
    "ci_high": 3.0 + 3.182446305 * (2.0 ** 0.5),
    "dof": 3,
}

# --- missing_period ------------------------------------------------------- #
# m1 is observed only post, m2 only pre. Both must be excluded; the estimable
# sample is exactly hand_2x2, so the estimate is unchanged.
MISSING_PERIOD_EXCLUDED = {"m1", "m2"}
MISSING_PERIOD_DID = 3.0

# --- nonparallel_pretrend ------------------------------------------------- #
# Pre periods 0,1 (onset = 2): treated period-over-period slopes 3.5, 4, 3
# (mean 3.5); controls 0.5, 0, 1 (mean 0.5). Slope gap (interaction) = 3.0.
NONPARALLEL_SLOPE_GAP = 3.0
NONPARALLEL_DID_0_2 = 6.0   # treated mean change 7 - control mean change 1

# --- contaminated_control ------------------------------------------------- #
# pre=0, post=2. t1 change 4; c1 change 0; c2 treated at period 1 (dirty).
CONTAMINATED_UNIT = "c2"
CONTAMINATED_CLEAN_DID = 4.0   # only c1 survives as control
CONTAMINATED_CLEAN_N_CONTROL = 1

# --- weighted_2x2 --------------------------------------------------------- #
# treated weighted change (3*10 + 1*2)/4 = 8
# control weighted change (1*4 + 3*0)/4  = 1
WEIGHTED_DID = 7.0

# --- staggered event study ------------------------------------------------ #
# tau_-2 = 0, tau_0 = 5, tau_1 = 8; -1 is the zero reference.
EVENT_TAU = {-2: 0.0, -1: 0.0, 0: 5.0, 1: 8.0}
EVENT_WINDOW = [-2, -1, 0, 1]
EVENT_OUT_OF_SUPPORT_K = 2
